package dev.pocketengine.features.plugins;

import static org.junit.Assert.*;
import android.app.Application;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.features.*;
import dev.pocketengine.features.local.runtime.*;
import java.lang.reflect.Modifier;
import java.nio.file.*;
import java.util.concurrent.*;
import org.json.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import org.robolectric.annotation.SQLiteMode;

/** Real native-owner API -> the original finite FeatureHost workers/task/fence/managed pipe.
 * No model account, fake task identity, public approval flag, alternate worker or dispatcher. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
@SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class McpLocalDiscoveryOwnerTest {
    static final class Fixture implements AutoCloseable {
        final McpLocalDiscoveryReviewTest.Fixture f;final FeatureHost host;final NativeOwnerWorkflows owner;
        Fixture()throws Exception{this("");}
        Fixture(String listPrefix)throws Exception{f=new McpLocalDiscoveryReviewTest.Fixture("python3","server.py",McpLocalDiscoveryNativeTest.python(McpStdioClient.VERSION,listPrefix));host=new FeatureHost(event->{},f.tasks,()->false);host.register(f.workspace);host.register(f.local);host.register(f.plugins);owner=new NativeOwnerWorkflows(host,f.context,f.tasks,new MemorySourceBridge(host,f.tasks));}
        JSONObject prepare()throws Exception{return owner.mcp("prepareLocalMcpDiscovery",new JSONObject().put("configuration",new JSONObject(f.config.toString())));}
        JSONObject confirm(JSONObject review)throws Exception{return owner.mcp("confirmLocalMcpDiscovery",new JSONObject().put("reviewId",review.getString("reviewId")).put("planDigest",review.getString("planDigest")));}
        JSONObject read(String task)throws Exception{return owner.mcp("readLocalMcpDiscovery",new JSONObject().put("taskId",task));}
        JSONObject finished(String task)throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(12);JSONObject result=null;while(System.nanoTime()<until){result=read(task);if(result.getString("status").matches("completed|failed"))return result;Thread.sleep(25);}throw new AssertionError("original native owner action did not settle: "+result);}
        RuntimeExecutionRef ref(String task)throws Exception{JSONObject job=f.tasks.ownerMcpDiscoveryForOwner(task).getJSONObject("nativeJob");return RuntimeExecutionRef.fromHost(job.getJSONObject("exact"),job.getJSONObject("binding"));}
        @Override public void close()throws Exception{host.close();f.close();}
    }
    @Test public void sourceChoicesDescriptionAndTypedReviewAreMetadataOnlyUntilTheExplicitConfirmation()throws Exception{try(Fixture x=new Fixture()){JSONObject choices=x.owner.mcp("localMcpDiscoveryChoices",new JSONObject());assertFalse(choices.getBoolean("executionAuthorized"));assertEquals(1,choices.getJSONArray("checkouts").length());JSONObject source=x.owner.mcp("describeLocalMcpWorkspace",new JSONObject().put("checkoutId",x.f.checkout));assertEquals(x.f.config.getString("expectedSourceDigest"),source.getString("sourceDigest"));assertFalse(source.getBoolean("sourceBodyIncluded"));assertFalse(source.getBoolean("wholeCheckoutVersion"));JSONObject review=x.prepare();assertTrue(review.getBoolean("previewOnly"));assertFalse(review.getBoolean("programStarted"));assertFalse(review.getBoolean("executionAuthorized"));assertEquals("per_operation_visible_copy",review.getString("executionWorkspace"));assertEquals(0,x.f.tasks.list().length());assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}}
    @Test public void explicitNativeConfirmationUsesTheOriginalWorkerAndLeavesOneTaskReceiptWithoutInstallingTools()throws Exception{try(Fixture x=new Fixture()){JSONObject review=x.prepare(),started=x.confirm(review);String id=started.getString("taskId");assertEquals(review.getString("actionId"),id);JSONObject actual=x.finished(id);assertEquals(actual.toString(),"completed",actual.getString("status"));assertTrue(actual.getJSONObject("receipt").getBoolean("metadataAvailable"));assertTrue(actual.getJSONObject("receipt").getJSONObject("processReceipt").getBoolean("resourcesReleased"));assertEquals(1,x.f.tasks.list().length());assertEquals(1,x.f.tasks.get(id,false).getJSONArray("operations").length());assertEquals(0,x.f.plugins.snapshot().getJSONArray("plugins").length());assertFalse(actual.has("nativeJob"));assertFalse(actual.toString().contains("--public-mode"));assertThrows(SecurityException.class,()->x.confirm(review));assertEquals("completed",x.read(id).getString("status"));assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}}
    @Test public void discardedOrWrongDigestReviewCannotBeTurnedIntoAnOwnerProgramLaunch()throws Exception{try(Fixture x=new Fixture()){JSONObject first=x.prepare();assertTrue(x.owner.mcp("discardLocalMcpReview",new JSONObject().put("reviewId",first.getString("reviewId"))).getBoolean("discarded"));assertThrows(SecurityException.class,()->x.confirm(first));JSONObject second=x.prepare();assertThrows(SecurityException.class,()->x.owner.mcp("confirmLocalMcpDiscovery",new JSONObject().put("reviewId",second.getString("reviewId")).put("planDigest","0".repeat(64))));assertEquals(0,x.f.tasks.list().length());assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}}
    @Test public void realAbortPolicyQueueRejectionUsesItsPrivateNeverEnteredProofNotAPlainException()throws Exception{try(Fixture x=new Fixture()){var field=FeatureHost.class.getDeclaredField("workers");field.setAccessible(true);ThreadPoolExecutor original=(ThreadPoolExecutor)field.get(x.host);assertEquals(ThreadPoolExecutor.AbortPolicy.class,original.getRejectedExecutionHandler().getClass());original.shutdown();McpLocalDiscovery.Confirmed approved=x.f.confirmed();String id=approved.actionId();assertThrows(IllegalStateException.class,()->x.host.submitMcpDiscoveryForOwner(approved));JSONObject row=x.f.tasks.ownerMcpDiscoveryForOwner(id),receipt=row.getJSONObject("receipt");assertEquals("failed",row.getString("status"));assertEquals("mcp_native_owner_queue_rejected",receipt.getString("code"));assertTrue(receipt.getBoolean("notDispatched"));assertTrue(receipt.getBoolean("nativeHostNeverEnteredDispatch"));assertFalse(receipt.getBoolean("nativeProcessReceiptAvailable"));assertNull(row.optJSONObject("nativeJob"));assertFalse(x.f.tasks.hasUnresolved(id));assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));assertFalse(Files.exists(x.f.android.getFilesDir().toPath().resolve("local-development/mcp-discovery-copies").resolve(id)));assertThrows(SecurityException.class,()->x.f.tasks.recordOwnerMcpDiscoveryQueueRejectedForOwner(approved,null));for(var constructor:FeatureHost.McpDiscoveryQueueRejected.class.getDeclaredConstructors())assertTrue(Modifier.isPrivate(constructor.getModifiers()));}}
    @Test public void actualSourceChangeBeforeTheRuntimeBoundaryCanCloseOnlyWithTheTypedNonEntryProof()throws Exception{try(Fixture x=new Fixture()){McpLocalDiscovery.Confirmed approved=x.f.confirmed();RunControl original=new RunControl();x.f.tasks.beginOwnerMcpDiscoveryForOwner(approved,original);Path file=x.f.android.getFilesDir().toPath().resolve("local-development/checkouts").resolve(x.f.checkout).resolve("files/server.py");Files.write(file,"raise Exception('owner changed source before dispatch')\n".getBytes(java.nio.charset.StandardCharsets.UTF_8));McpLocalDiscoveryPipe.NotDispatched proof=assertThrows(McpLocalDiscoveryPipe.NotDispatched.class,()->McpLocalDiscoveryPipe.run(approved,x.f.tasks,original));x.f.tasks.recordOwnerMcpDiscoveryNotDispatchedForOwner(approved,proof);JSONObject row=x.f.tasks.ownerMcpDiscoveryForOwner(approved.actionId());assertEquals("failed",row.getString("status"));assertTrue(row.getJSONObject("receipt").getBoolean("notDispatched"));assertFalse(row.getJSONObject("receipt").getBoolean("nativeProcessReceiptAvailable"));assertNull(row.optJSONObject("nativeJob"));assertFalse(x.f.tasks.hasUnresolved(approved.actionId()));assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));assertThrows(SecurityException.class,()->x.f.tasks.recordOwnerMcpDiscoveryNotDispatchedForOwner(approved,proof));}}
    @Test public void explicitNativeCancelReachesTheSameRunningOwnerControlAndOriginalProcess()throws Exception{try(Fixture x=new Fixture("  time.sleep(20)\n")){String id=x.confirm(x.prepare()).getString("taskId");long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);boolean waiting=false;while(System.nanoTime()<until){JSONObject row=x.f.tasks.ownerMcpDiscoveryForOwner(id);if(row.optJSONObject("nativeJob")!=null)try{if(x.f.runtime.query(x.ref(id)).json().optString("stderr").contains("OWN_METHOD:tools/list")){waiting=true;break;}}catch(IllegalArgumentException unpublishedOriginalRef){}Thread.sleep(20);}assertTrue(waiting);x.owner.mcp("cancelLocalMcpDiscovery",new JSONObject().put("taskId",id));JSONObject stopped=x.finished(id);assertEquals(stopped.toString(),"failed",stopped.getString("status"));assertTrue(stopped.getJSONObject("receipt").getJSONObject("processReceipt").getBoolean("resourcesReleased"));assertFalse(x.f.tasks.hasUnresolved(id));assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));assertEquals(1,x.f.tasks.list().length());}}
    @Test public void nativeLocalMcpApprovalIsNotAModelFeatureCommandOrAnHttpDiscoveryGrant()throws Exception{try(Fixture x=new Fixture()){assertThrows(IllegalArgumentException.class,()->x.f.plugins.handle("prepareLocalMcpDiscovery",new JSONObject().put("configuration",x.f.config)));assertThrows(IllegalArgumentException.class,()->x.f.local.handle("confirmLocalMcpDiscovery",new JSONObject().put("approved",true)));assertThrows(SecurityException.class,()->x.owner.mcp("confirmLocalMcpDiscovery",new JSONObject().put("reviewId",java.util.UUID.randomUUID().toString()).put("planDigest","0".repeat(64))));assertEquals(0,x.f.tasks.list().length());}}
    @Test public void integratedOriginalTaskStoreRetainsTheProfileGuardAndTheMcpNoRunnerGuard()throws Exception{try(Fixture x=new Fixture()){String ordinary=x.f.tasks.createCapabilityTask("No reviewed profile; cannot become a generic model run","").getString("id");JSONObject legacy=x.f.tasks.startAttempt(ordinary,"capabilities",1);x.f.tasks.endAttempt(ordinary,legacy.getString("runId"),"paused","Original legacy task remains usable",new JSONObject());
        var settings=new dev.pocketengine.store.SettingsStore(x.f.android);
        var sources=new dev.pocketengine.features.controlplane.WorkProfileResolver.Sources(){public dev.pocketengine.core.ModelConfig model(dev.pocketengine.runtime.models.ModelTargetRef r,String p,RunControl c){throw new AssertionError("Empty explicit profile cannot infer a model");}public void checkModel(dev.pocketengine.core.ModelConfig m,String p,RunControl c){throw new AssertionError();}public JSONObject skill(String id,RunControl c){throw new AssertionError();}public JSONObject plugin(String id,RunControl c){throw new AssertionError();}public JSONObject extension(String id,RunControl c){throw new AssertionError();}public JSONObject team(String id,RunControl c){throw new AssertionError();}public JSONObject target(JSONObject r,RunControl c){throw new AssertionError();}public java.util.Set<String> hostCapabilities(){return java.util.Set.of();}};
        var profiles=new dev.pocketengine.features.controlplane.NativeWorkProfileHost(settings,sources);try(var page=profiles.newOwnerPage()){page.setForeground(true);JSONObject saved=page.save("",0,"Native preserved explicit profile",dev.pocketengine.features.controlplane.WorkProfile.definition("draft-profile",1,"Explicit empty profile"));var review=page.review(saved.getString("profileId"),saved.getLong("revision"),new RunControl());RunControl profileControl=new RunControl();var selection=page.select(review,review.digest,profileControl);JSONObject pending=x.f.tasks.createCapabilityTaskWithWorkProfile("Keep the original real profile pointer","",selection,profileControl);SecurityException profileDenied=assertThrows(SecurityException.class,()->x.f.tasks.startAttempt(pending.getString("id"),"capabilities",1));assertTrue(profileDenied.getMessage().contains("工作配置"));}
        McpLocalDiscovery.Confirmed approved=x.f.confirmed();RunControl original=new RunControl();x.f.tasks.beginOwnerMcpDiscoveryForOwner(approved,original);SecurityException denied=assertThrows(SecurityException.class,()->x.f.tasks.startAttempt(approved.actionId(),"capabilities",1));assertTrue(denied.getMessage().contains("MCP"));}}
    @Test public void untrustedExecutorContractCannotSignAQueueRejectionOrEraseAnUnknownOperation()throws Exception{try(Fixture x=new Fixture()){var field=FeatureHost.class.getDeclaredField("workers");field.setAccessible(true);ThreadPoolExecutor original=(ThreadPoolExecutor)field.get(x.host);original.shutdown();original.setRejectedExecutionHandler((action,pool)->{pool.getQueue().offer(action);throw new RejectedExecutionException("own counterexample accepted the action into a late queue");});McpLocalDiscovery.Confirmed approved=x.f.confirmed();assertThrows(IllegalStateException.class,()->x.host.submitMcpDiscoveryForOwner(approved));JSONObject row=x.f.tasks.ownerMcpDiscoveryForOwner(approved.actionId());assertEquals("reconciling",row.getString("status"));assertNull(row.optJSONObject("receipt"));assertTrue(x.f.tasks.hasUnresolved(approved.actionId()));assertNull(row.optJSONObject("nativeJob"));assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));assertThrows(SecurityException.class,()->x.f.tasks.resolveOperation(approved.actionId(),approved.actionId(),"not_occurred"));assertThrows(SecurityException.class,()->x.f.tasks.reconcileExternalTask(approved.actionId(),"not_occurred","No original process proof"));assertTrue(x.f.tasks.hasUnresolved(approved.actionId()));}}

    @Test public void mcpReconciliationGuardDoesNotDisableTheOriginalNonMcpOwnerReconciliation()throws Exception{try(Fixture x=new Fixture()){String id=java.util.UUID.randomUUID().toString();x.f.tasks.beginExternal("local","own_non_mcp_fixture",id,new JSONObject());x.f.tasks.status(id,"reconciling","Original external fixture without a process");JSONObject result=x.f.tasks.reconcileExternalTask(id,"not_occurred","Owner inspected this independent non-MCP fixture");assertEquals("awaiting_user",result.getString("status"));assertFalse(result.has("ownerMcpDiscovery"));}}

}
